function tuneTarget(p){const d=p.deck.map(k=>k.endsWith('_plus')?k.slice(0,-5):k);let best=null,bestN=1e9;for(const k of tuneable){const i=d.indexOf(k);if(i>=0&&(p.tuning?.[k]||0)<bestN){bestN=p.tuning?.[k]||0;best=k;}}return best;}
