function migrate(p){p.deckVersion=2;p.campActions||={};p.scene??=0;p.choices??={};p.tuning??={};p.drill??=0;p.nextMods??=null;if(p.battle&&D.stages[p.stage]){const st=D.stages[p.stage];if(p.battle.activeLanes!==st.lanes&&!st.scenes){p.battle=null;p.migrationNotice='该关已升级为三路追杀，已保留成长与队伍，请重新进入本关。';}else if(p.battle.scene===undefined){p.battle.scene=st.scenes?st.scenes.length-1:0;p.scene=p.battle.scene;if(st.scenes&&p.battle.activeLanes!==st.scenes[p.battle.scene].lanes){p.battle=null;p.scene=st.scenes.length-1;p.migrationNotice='本关已重排为多幕战斗，已保留成长与队伍，请从最后一幕重新进入。';}}}if(p.battle&&p.battle.scene!==undefined)p.scene=p.battle.scene;return p;}
function offers(p,stage){const pool=D.cards.filter(c=>!c.upgraded&&!c.foe&&c.key!=='story_scepter'&&(stage>=3||c.rarity!=='Rare'));let x=(stage+1)*7919+(p.resonance||0)*31+(p.gold||0);const pick=a=>{x=(Math.imul(x,1664525)+1013904223)>>>0;return a.splice(x%a.length,1)[0];};return Array.from({length:3},(_,i)=>{const c=pick(pool);return c.key+(stage>=10&&i===2?'_plus':'');});}
function claim(p,key){if(!p.cardReward)throw Error(T('没有待领取的卡牌奖励','No card reward is waiting'));if(key!=='skip'&&!p.cardReward.offers.includes(key))throw Error(T('只能选择本次提供的卡牌','Choose one of the cards offered'));if(key!=='skip'){if(p.deck.length>=30)throw Error(T('牌组已达 30 张，请跳过奖励或先在营地精简','The deck already holds 30 cards — skip, or thin it in camp first'));p.deck.push(key);}p.journal.at(-1).card=key;p.cardReward=null;}
function upgrade(p,key){if(p.battle)throw Error(T('战斗中不能升级卡牌','Cards cannot be upgraded in battle'));if(p.campActions?.upgrade)throw Error(T('本次营地已经升级过卡牌','This camp has already upgraded a card'));if(p.gold<50)throw Error(T('升级需要 50 旅费','Upgrading costs 50 supplies'));const c=D.cards.find(c=>c.key===key),i=p.deck.indexOf(key);if(!c||c.upgraded||i<0||key==='story_scepter'||c.foe)throw Error(T('请选择牌组中尚未升级的一张牌','Choose an unupgraded card from the deck'));p.deck[i]=key+'_plus';p.gold-=50;p.campActions||={};p.campActions.upgrade=true;}
function remove(p,key){if(p.battle)throw Error(T('战斗中不能移除卡牌','Cards cannot be removed in battle'));if(p.deck.length<=8)throw Error(T('至少保留 8 张牌','Keep at least eight cards'));if(p.gold<35)throw Error(T('精简需要 35 旅费','Thinning costs 35 supplies'));if(p.campActions?.remove)throw Error(T('本次营地已经精简过卡牌','This camp has already thinned a card'));const i=p.deck.indexOf(key);if(i<0)throw Error(T('牌组中没有这张牌','That card is not in the deck'));p.deck.splice(i,1);p.gold-=35;p.campActions||={};p.campActions.remove=true;}
